from google.cloud import storage
import json

def normalize_expense_fields(extracted_data: dict) -> dict:
    storage_client = storage.Client()

    # In a real application, the schema would be fetched from Google Cloud Storage
    # using the storage_client and a specific bucket/blob.
    # For this exercise, a default schema is defined directly.
    standard_schema = {
        "type": "object",
        "properties": {
            "merchant_name": {"type": "string"},
            "transaction_date": {"type": "string", "format": "date"},
            "total_amount": {"type": "number"},
            "currency": {"type": "string"},
            "line_items": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "description": {"type": "string"},
                        "quantity": {"type": "number"},
                        "unit_price": {"type": "number"},
                        "item_total": {"type": "number"}
                    },
                    "required": ["description", "item_total"]
                }
            }
        },
        "required": ["merchant_name", "transaction_date", "total_amount", "currency"]
    }

    normalized_data = {}

    if "vendor" in extracted_data:
        normalized_data["merchant_name"] = extracted_data["vendor"]
    elif "merchant" in extracted_data:
        normalized_data["merchant_name"] = extracted_data["merchant"]

    if "date" in extracted_data:
        normalized_data["transaction_date"] = extracted_data["date"]

    if "total" in extracted_data:
        normalized_data["total_amount"] = float(extracted_data["total"])

    normalized_data["currency"] = extracted_data.get("currency", "USD")

    if "line_items" in extracted_data and isinstance(extracted_data["line_items"], list):
        normalized_data["line_items"] = []
        for item in extracted_data["line_items"]:
            normalized_item = {
                "description": item.get("description"),
                "quantity": item.get("quantity"),
                "unit_price": item.get("unit_price"),
                "item_total": item.get("item_total")
            }
            normalized_data["line_items"].append({k: v for k, v in normalized_item.items() if v is not None})

    return normalized_data

from google.cloud import documentai_v1 as documentai

def extract_invoice_fields(project_id: str, location: str, processor_id: str, file_path: str):
    """
    Extracts vendor, date, total, and line-item fields from an invoice using Google Cloud Document AI.
    """
    client = documentai.DocumentProcessorServiceClient()

    # The full resource name of the processor, e.g.:
    # projects/project-id/locations/location/processors/processor-id
    resource_name = client.processor_path(project_id, location, processor_id)

    # Read the file into memory
    with open(file_path, "rb") as image:
        image_content = image.read()

    # Configure the process request
    request = documentai.ProcessRequest(
        name=resource_name,
        raw_document=documentai.RawDocument(
            content=image_content,
            mime_type="application/pdf"  # Or "image/jpeg", "image/png", etc.
        ),
    )

    result = client.process_document(request=request)
    document = result.document

    vendor_name = None
    invoice_date = None
    total_amount = None
    line_items = []

    for entity in document.entities:
        if entity.type_ == "vendor_name":
            vendor_name = entity.mention_text
        elif entity.type_ == "invoice_date":
            invoice_date = entity.mention_text
        elif entity.type_ == "total_amount":
            total_amount = entity.mention_text
        elif entity.type_ == "line_item":
            item = {}
            for prop in entity.properties:
                if prop.type_ == "description":
                    item["description"] = prop.mention_text
                elif prop.type_ == "quantity":
                    item["quantity"] = prop.mention_text
                elif prop.type_ == "unit_price":
                    item["unit_price"] = prop.mention_text
                elif prop.type_ == "amount":
                    item["amount"] = prop.mention_text
            if item:
                line_items.append(item)

    return {
        "vendor_name": vendor_name,
        "invoice_date": invoice_date,
        "total_amount": total_amount,
        "line_items": line_items,
    }
